"""
Titanic数据集分析脚本
完成数据清洗、特征工程、可视化和报告生成
"""

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import logging
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# 设置日志
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

# 设置中文字体和样式
plt.style.use('default')
sns.set_palette("husl")

def load_data():
    """加载Titanic数据集"""
    logger.info("正在加载Titanic数据集...")
    df = pd.read_csv('ml_datasets/titanic.csv')
    logger.info(f"数据集加载完成，形状: {df.shape}")
    return df

def check_missing_values(df):
    """检查缺失值"""
    logger.info("检查缺失值...")
    missing_info = df.isnull().sum()
    missing_percent = (missing_info / len(df)) * 100

    missing_df = pd.DataFrame({
        'Missing Count': missing_info,
        'Missing Percentage': missing_percent
    })
    missing_df = missing_df[missing_df['Missing Count'] > 0].sort_values('Missing Count', ascending=False)

    logger.info("缺失值统计:")
    for col, row in missing_df.iterrows():
        logger.info(f"  {col}: {row['Missing Count']} ({row['Missing Percentage']:.1f}%)")

    return missing_df

def fill_missing_values(df):
    """填充缺失值"""
    logger.info("开始填充缺失值...")
    df_clean = df.copy()

    # 填充age列 - 使用均值
    if df_clean['age'].isnull().any():
        age_mean = df_clean['age'].mean()
        df_clean['age'].fillna(age_mean, inplace=True)
        logger.info(f"age列缺失值已用均值填充: {age_mean:.1f}")

    # 填充deck列 - 使用众数或删除（这里选择用'Unknown'填充）
    if df_clean['deck'].isnull().any():
        df_clean['deck'].fillna('Unknown', inplace=True)
        logger.info("deck列缺失值已用'Unknown'填充")

    # 填充embarked列的少数缺失值
    if df_clean['embarked'].isnull().any():
        embarked_mode = df_clean['embarked'].mode()[0]
        df_clean['embarked'].fillna(embarked_mode, inplace=True)
        logger.info(f"embarked列缺失值已用众数填充: {embarked_mode}")

    return df_clean

def convert_to_categorical(df):
    """转换为分类变量"""
    logger.info("转换embarked和class为分类变量...")
    df['embarked'] = df['embarked'].astype('category')
    df['class'] = df['class'].astype('category')
    logger.info("分类变量转换完成")
    return df

def calculate_survival_rates(df):
    """计算生存率"""
    logger.info("计算不同群体的生存率...")

    # 按性别计算生存率
    survival_by_sex = df.groupby('sex')['survived'].agg(['count', 'sum', 'mean']).round(3)
    survival_by_sex.columns = ['Total', 'Survived', 'Survival_Rate']

    # 按舱位等级计算生存率
    survival_by_class = df.groupby('class')['survived'].agg(['count', 'sum', 'mean']).round(3)
    survival_by_class.columns = ['Total', 'Survived', 'Survival_Rate']

    # 按性别和舱位等级计算生存率
    survival_by_sex_class = df.groupby(['sex', 'class'])['survived'].agg(['count', 'sum', 'mean']).round(3)
    survival_by_sex_class.columns = ['Total', 'Survived', 'Survival_Rate']

    logger.info("生存率计算完成")
    return survival_by_sex, survival_by_class, survival_by_sex_class

def create_visualizations(df, survival_by_sex, survival_by_class, survival_by_sex_class):
    """创建可视化图表"""
    logger.info("生成可视化图表...")

    # 创建子图
    fig, axes = plt.subplots(2, 2, figsize=(15, 12))
    fig.suptitle('Titanic Dataset Analysis - Survival Rates', fontsize=16, fontweight='bold')

    # 1. 按性别的生存率
    survival_by_sex['Survival_Rate'].plot(kind='bar', ax=axes[0,0], color=['skyblue', 'lightcoral'])
    axes[0,0].set_title('Survival Rate by Gender')
    axes[0,0].set_ylabel('Survival Rate')
    axes[0,0].tick_params(axis='x', rotation=0)
    for i, v in enumerate(survival_by_sex['Survival_Rate']):
        axes[0,0].text(i, v + 0.01, f'{v:.3f}', ha='center', va='bottom')

    # 2. 按舱位等级的生存率
    survival_by_class['Survival_Rate'].plot(kind='bar', ax=axes[0,1], color=['gold', 'lightgreen', 'lightblue'])
    axes[0,1].set_title('Survival Rate by Class')
    axes[0,1].set_ylabel('Survival Rate')
    axes[0,1].tick_params(axis='x', rotation=0)
    for i, v in enumerate(survival_by_class['Survival_Rate']):
        axes[0,1].text(i, v + 0.01, f'{v:.3f}', ha='center', va='bottom')

    # 3. 按性别和舱位等级的生存率（热力图）
    pivot_data = survival_by_sex_class.reset_index().pivot(index='sex', columns='class', values='Survival_Rate')
    sns.heatmap(pivot_data, annot=True, fmt='.3f', cmap='YlOrRd', ax=axes[1,0])
    axes[1,0].set_title('Survival Rate by Gender and Class')

    # 4. 年龄分布和生存情况
    df[df['survived']==1]['age'].hist(alpha=0.7, bins=30, label='Survived', ax=axes[1,1], color='green')
    df[df['survived']==0]['age'].hist(alpha=0.7, bins=30, label='Did not survive', ax=axes[1,1], color='red')
    axes[1,1].set_title('Age Distribution by Survival')
    axes[1,1].set_xlabel('Age')
    axes[1,1].set_ylabel('Count')
    axes[1,1].legend()

    plt.tight_layout()
    plt.savefig('titanic_survival_analysis.png', dpi=300, bbox_inches='tight')
    plt.close()
    logger.info("可视化图表已保存为 titanic_survival_analysis.png")

    return 'titanic_survival_analysis.png'

def create_is_alone_feature(df):
    """创建is_alone特征"""
    logger.info("创建is_alone特征...")
    df['is_alone'] = (df['sibsp'] + df['parch']) == 0
    alone_count = df['is_alone'].sum()
    total_count = len(df)
    logger.info(f"is_alone特征创建完成，独自旅行的乘客: {alone_count}/{total_count} ({alone_count/total_count*100:.1f}%)")
    return df

def save_clean_data(df):
    """保存清洗后的数据"""
    logger.info("保存清洗后的数据...")
    df.to_csv('titanic_clean.csv', index=False)
    logger.info("清洗后的数据已保存为 titanic_clean.csv")

