</body>
</html>
"""

    with open('report.html', 'w', encoding='utf-8') as f:
        f.write(html_content)

    logger.info("HTML报告已生成: report.html")

def main():
    """主函数"""
    logger.info("=" * 50)
    logger.info("开始Titanic数据集分析")
    logger.info("=" * 50)

    try:
        # 1. 加载数据
        df = load_data()

        # 2. 检查缺失值
        missing_df = check_missing_values(df)

        # 3. 填充缺失值
        df_clean = fill_missing_values(df)

        # 4. 转换为分类变量
        df_clean = convert_to_categorical(df_clean)

        # 5. 创建is_alone特征
        df_clean = create_is_alone_feature(df_clean)

        # 6. 计算生存率
        survival_by_sex, survival_by_class, survival_by_sex_class = calculate_survival_rates(df_clean)

        # 7. 创建可视化
        chart_file = create_visualizations(df_clean, survival_by_sex, survival_by_class, survival_by_sex_class)

        # 8. 保存清洗后的数据
        save_clean_data(df_clean)

        # 9. 生成HTML报告
        generate_html_report(df_clean, missing_df, survival_by_sex, survival_by_class, survival_by_sex_class, chart_file)

        logger.info("=" * 50)
        logger.info("所有任务完成！")
        logger.info("输出文件:")
        logger.info("  - titanic_clean.csv (清洗后的数据)")
        logger.info("  - titanic_survival_analysis.png (可视化图表)")
        logger.info("  - report.html (完整分析报告)")
        logger.info("=" * 50)

    except Exception as e:
        logger.error(f"处理过程中出现错误: {str(e)}")
        raise

if __name__ == "__main__":
